export async function forceReconnectV2() {
    const reconnectPromises = [];
    const isServer = (await getConfig()).isServer;
    for (const [appId, connection] of connections) {
        if (!connection.ws) {
            continue;
        }
        // Store subscriptions to restore
        const subscriptionsToRestore = Array.from(connection.subscriptions.values());
        // Close the connection
        connection.ws.close();
        connection.ws = null;
        connection.isConnected = false;
        connections.delete(appId);
        // If there were active subscriptions, re-establish connection
        if (subscriptionsToRestore.length > 0) {
            const reconnectPromise = (async () => {
                // Get fresh connection
                const newConnection = await getOrCreateConnection(appId, isServer);
                // Re-register all subscriptions
                for (const sub of subscriptionsToRestore) {
                    newConnection.subscriptions.set(sub.subscriptionId, sub);
                }
                // Wait for connection to be ready, then re-subscribe
                // The 'open' handler in getOrCreateConnection will send subscribe messages
            })();
            reconnectPromises.push(reconnectPromise);
        }
    }
    await Promise.all(reconnectPromises);
}
